"""Helpers used for camera-guided motions during the recorded episode."""
import numpy as np
from scipy.spatial.transform import Rotation as Rot, Slerp

def jact(rows, label='joint_move', dt=.2):
    with (OUT/'joint_actions.jsonl').open('a') as f:
        f.write(json.dumps({'rows': np.asarray(rows).tolist(), 'label': label, 'dt': dt})+'\n')
    return save(r.submit('joint_position', rows, dt=dt, note=label, video='none', depth=True), label)

def jmove(q, grip, label, secs=4):
    q0=np.array(obs.meta['proprio']['now'][:7]); n=int(secs/.2)
    t=np.linspace(0,1,n); s=10*t**3-15*t**4+6*t**5
    return jact([[*((1-a)*q0+a*np.array(q)),grip] for a in s], label)

def jpose(pose, grip, label, secs=3):
    sol=r.ik({'tcp':pose}, seed=obs.meta['proprio']['now'][:7])
    if not sol['ok']: raise RuntimeError('No accurate IK solution')
    return jmove(sol['q'], grip, label, secs)

def jcart(pose, grip, label, secs=3):
    curr=np.array(obs.meta['proprio']['now'][8:15]); end=np.array(pose)
    seed=np.array(obs.meta['proprio']['now'][:7]); n=int(secs/.2)
    t=np.linspace(0,1,n); smooth=10*t**3-15*t**4+6*t**5
    rots=Rot.from_quat([[*curr[4:7],curr[3]],[*end[4:7],end[3]]]); sl=Slerp([0,1],rots)
    rows=[]
    for a in smooth:
        qq=sl(a).as_quat(); pp=(1-a)*curr[:3]+a*end[:3]
        sol=r.ik({'tcp':[*pp,qq[3],*qq[:3]]}, seed=seed)
        if not sol['ok']: raise RuntimeError(str(sol))
        if np.max(abs(np.array(sol['q'])-seed))>.3: raise RuntimeError('Large IK jump')
        seed=np.array(sol['q']); rows.append([*seed,grip])
    return jact(rows,label)
PY","max_output_tokens":200}));
